-- Oracle (23ai or newer) script for the categories table.
-- Column names match the Category entity and JdbcCategoryDao.
-- WARNING: running this script deletes the existing categories table and all its data.

DROP TABLE IF EXISTS categories;

CREATE TABLE categories (
    id      NUMBER(10)          GENERATED BY DEFAULT AS IDENTITY,
    name    VARCHAR2(100 CHAR)  NOT NULL,
    slug    VARCHAR2(100 CHAR)  NOT NULL,
    active  BOOLEAN             NOT NULL,
    CONSTRAINT pk_categories PRIMARY KEY (id)
);

